fn v3_epicops_buff_window(self:&mut TeamPlan, version:usize, rnd:&mut StdRng,
                          player:&PlayerState, data:&OperationData,
                          goal_data:&GoalData, plan:&BigPlan) -> bool

// ── 1) 수리(리페어) 우선 ── L635
// 호출은 ArgPromotion 으로 (player.info.team: i64, data.cache: ptr, plan) 형태로 풀려 있다.
// 반환은 u8, range(0,3) → switch { 1, 2, default }
match v3_epicops_repair_need(player, data, plan) {
  1 => {                                                       // L637~638
        self.objective = Some(MainObjective::Repair);           // +0x41f = 7
        self.chats.push(Chat::Repair(0));                       // 태그 23, payload@+8 = 0
        return true;
      }
  2 => {                                                       // L642
        self.objective = Some(MainObjective::Repair);           // +0x41f = 7
        return true;                                            // ★채팅 없음 (1과의 유일한 차이)
      }
  _ => {}                                                      // 0 → 아래로 진행
}

// ── 2) 적이 오브젝트 먹는 중이면 세르펜 경합 ── L651~658
if is_object_being_taken_by_enemy(player, data, goal_data, self, /*bool 상수*/ true)   // L651
   && v3_serpen_contest_clear_win(version, player, data, self) {                        // L652
     self.eo_serpen_punish_issues += 1;                                        // L653, +0x410
     self.objective = Some(MainObjective::Serpen{ phase: ObjectPhase::Setup,    // L654
                                                  with_battle: true });        // 바이트 1,1,1
     self.chats.push(Chat::SerpenSetup(0));                                    // L658, 태그 25
     return true;
}
// ⚠단락평가: is_object_being_taken_by_enemy 가 false 이거나 clear_win 이 false 면 둘 다 아래 3)으로 간다.

// ── 3) 에픽 압박 라인 공지 ── L664~679
let strategy: Strategy = player.strategy(rnd, data.cache.game);   // L664, sret 24B
let g: i8 = v3_epic_group_line(strategy.morgard_use, player, data);  // L665, Option<LineType> (-1=None)
if g == -1 { return false; }                                      // 라인 못 정하면 종료
let group_line: LineType = g;                                     // 0=Top 1=Mid 2=Bottom

if self.v3_press_chat_line == Some(group_line) { return false; }   // L666, Option<LineType>::ne
// (같은 라인이면 아무것도 안 하고 종료 = 중복 공지 방지 게이트)

// L667~670: (0..5).find(...) — 5회 완전 언롤됨
let team  = player.info.team;                    // team>=2 면 panic_bounds_check(team, 2)
let slots = &data.cache.player_champion[team];   // [Option<&Entity>;5] @ cache+0x1e0
let announcer: Option<usize> = (0..5).find(|&x| {
        slots[x].is_some()                                                       // L668, null 비교
     && v3_epic_formation_role(strategy.morgard_use,                             // L669
                               Position::from_index(x), player, data)
          .is_some_and(|f| !f.is_split)                                          // L670
   });
// ★L670 의 IR 표현: r = extractvalue(role,0) 즉 Option<V3EpicFormation> 의 byte0.
//   V3EpicFormation{ is_split: bool @byte0, line: LineType @byte1 } 이고
//   Option 니치가 is_split 자리를 써서 None = 2.
//   컴파일러가 (r != 2) XOR (r & 1) 로 접었다 = is_some && !is_split.
//   진리표: r=0 → true / r=1(is_split) → false / r=2(None) → false.
//   byte1(line)은 poison — 이 술어는 라인을 안 본다.

// L672
if announcer == Some(player.info.position.as_index()) {   // as_index = +0x9c0 의 i32 를 zext
    // L673: 나 자신이 이번 라인 변경의 대표(아나운서)일 때만 채팅
    self.chats.push(
        if self.v3_press_chat_line.is_none() { Chat::Press(group_line, 0) }        // 태그 21
        else                                 { Chat::PressChange(group_line, 0) }  // 태그 22
    );
}
self.v3_press_chat_line = Some(group_line);   // L679, +0x41e — ★announcer 여부와 무관하게 항상 갱신
return false;

// ── 반환값 정리(IR 의 phi) ──
//   true  : repair_need==1(L638 뒤), repair_need==2(L642 뒤), 세르펜 경합 성립(L658 뒤)
//   false : group_line==None(L665), 라인이 이전과 같음(L666), 압박라인 공지 처리 후(L679)
